// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/// @title Chain Loot Weapons — equippable gear for heroes in Zombie Siege
contract GameWeapon is ERC721, ERC721Enumerable, AccessControl {
    using Strings for uint256;

    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

  // 0=Sword 1=Bow 2=Staff 3=Hammer 4=Dagger
    struct WeaponStats {
        uint8 weaponType;
        uint8 damage;
        uint8 crit;
        uint8 rarity;
    }

    uint256 private _nextTokenId;
    uint256 public constant MAX_SUPPLY = 20_000;
    uint256 public mintPrice = 25 ether;
    address public paymentToken;
    address public treasury;

    mapping(uint256 => WeaponStats) public weaponStats;
    mapping(address => uint256) public mintedCount;
    uint256 public maxPerWallet = 30;

    event WeaponMinted(address indexed player, uint256 tokenId, uint8 weaponType, uint8 rarity);

    constructor(address admin, address _paymentToken, address _treasury)
        ERC721("Chain Loot Weapon", "WLOOT")
    {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(MINTER_ROLE, admin);
        paymentToken = _paymentToken;
        treasury = _treasury;
    }

    function totalMinted() external view returns (uint256) {
        return _nextTokenId;
    }

    function mintWeapon() external returns (uint256) {
        require(_nextTokenId < MAX_SUPPLY, "Max weapon supply");
        require(mintedCount[msg.sender] < maxPerWallet, "Mint cap");
        require(
            IERC20(paymentToken).transferFrom(msg.sender, treasury, mintPrice),
            "Payment failed"
        );

        uint256 tokenId = _nextTokenId++;
        _safeMint(msg.sender, tokenId);

        uint8 rarity = _rollRarity(tokenId);
        uint8 wType = uint8(uint256(keccak256(abi.encodePacked(tokenId, msg.sender))) % 5);
        weaponStats[tokenId] = WeaponStats({
            weaponType: wType,
            damage: _statForRarity(rarity, 15, 80),
            crit: _statForRarity(rarity, 5, 35),
            rarity: rarity
        });

        mintedCount[msg.sender]++;
        emit WeaponMinted(msg.sender, tokenId, wType, rarity);
        return tokenId;
    }

    function bonusDamage(uint256 tokenId) external view returns (uint256) {
        WeaponStats memory w = weaponStats[tokenId];
        return uint256(w.damage) + _rarityBonus(w.rarity);
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        WeaponStats memory w = weaponStats[tokenId];
        return string(
            abi.encodePacked(
                "data:application/json,{",
                '"name":"', _typeName(w.weaponType), " #", tokenId.toString(), '",',
                '"description":"Weapon for Chain Loot Zombie Siege",',
                '"attributes":[',
                '{"trait_type":"Type","value":"', _typeName(w.weaponType), '"},',
                '{"trait_type":"Rarity","value":"', _rarityName(w.rarity), '"},',
                '{"trait_type":"Damage","value":', uint256(w.damage).toString(), "},",
                '{"trait_type":"Crit","value":', uint256(w.crit).toString(), "}",
                "]}"
            )
        );
    }

    function _rarityBonus(uint8 rarity) private pure returns (uint256) {
        if (rarity == 4) return 30;
        if (rarity == 3) return 18;
        if (rarity == 2) return 10;
        if (rarity == 1) return 5;
        return 0;
    }

    function _rollRarity(uint256 tokenId) private view returns (uint8) {
        uint256 roll = uint256(keccak256(abi.encodePacked(block.prevrandao, msg.sender, tokenId))) % 100;
        if (roll < 3) return 4;
        if (roll < 10) return 3;
        if (roll < 25) return 2;
        if (roll < 50) return 1;
        return 0;
    }

    function _statForRarity(uint8 rarity, uint8 base, uint8 max_) private pure returns (uint8) {
        uint256 range = max_ - base;
        return uint8(base + (range * (rarity + 1)) / 5);
    }

    function _rarityName(uint8 r) private pure returns (string memory) {
        if (r == 4) return "Legendary";
        if (r == 3) return "Epic";
        if (r == 2) return "Rare";
        if (r == 1) return "Uncommon";
        return "Common";
    }

    function _typeName(uint8 t) private pure returns (string memory) {
        if (t == 4) return "Dagger";
        if (t == 3) return "Hammer";
        if (t == 2) return "Staff";
        if (t == 1) return "Bow";
        return "Sword";
    }

    function supportsInterface(bytes4 interfaceId)
        public view override(ERC721, ERC721Enumerable, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    function _update(address to, uint256 tokenId, address auth)
        internal override(ERC721, ERC721Enumerable)
        returns (address)
    {
        return super._update(to, tokenId, auth);
    }

    function _increaseBalance(address account, uint128 value)
        internal override(ERC721, ERC721Enumerable)
    {
        super._increaseBalance(account, value);
    }
}

contracts/ZombieSiegeUpgradeable.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./GameToken.sol";
import "./GameHero.sol";
import "./GameWeapon.sol";

/// @title Zombie Siege (UUPS Upgradeable) — on-chain P2E zombie combat for Chain Loot
/// @notice Defeat zombies with hero + weapon NFTs to earn LOOT. Upgradeable for future game features.
contract ZombieSiegeUpgradeable is
    Initializable,
    AccessControlUpgradeable,
    UUPSUpgradeable,
    ReentrancyGuard
{
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    string public constant VERSION = "1.0.0";

    GameToken public lootToken;
    GameHero public heroNft;
    GameWeapon public weaponNft;

    uint256 public fightCooldown;

    struct ZombieTier {
        string name;
        uint256 minPower;
        uint256 reward;
    }

    ZombieTier[5] public tiers;

    mapping(address => uint256) public totalKills;
    mapping(address => uint256) public totalLootEarned;
    mapping(uint256 => uint256) public heroLastFight;
    mapping(uint256 => uint256) public heroKillCount;
    mapping(uint256 => uint256) public heroEquippedWeapon;

    event BattleResult(
        address indexed player,
        uint256 indexed heroId,
        uint8 tier,
        bool victory,
        uint256 power,
        uint256 reward
    );
    event WeaponLinked(uint256 indexed heroId, uint256 indexed weaponId);
    event ContractUpgraded(string version);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address admin, address token, address hero, address weapon) public initializer {
        __AccessControl_init();

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(UPGRADER_ROLE, admin);

        lootToken = GameToken(token);
        heroNft = GameHero(hero);
        weaponNft = GameWeapon(weapon);
        fightCooldown = 30 seconds;

        tiers[0] = ZombieTier("Shambler", 40, 2 ether);
        tiers[1] = ZombieTier("Runner", 70, 5 ether);
        tiers[2] = ZombieTier("Brute", 110, 10 ether);
        tiers[3] = ZombieTier("Elite", 160, 20 ether);
        tiers[4] = ZombieTier("Necromancer", 220, 40 ether);
    }

    function equipWeapon(uint256 heroId, uint256 weaponId) external {
        require(heroNft.ownerOf(heroId) == msg.sender, "Not hero owner");
        if (weaponId != 0) {
            require(weaponNft.ownerOf(weaponId) == msg.sender, "Not weapon owner");
        }
        heroEquippedWeapon[heroId] = weaponId;
        emit WeaponLinked(heroId, weaponId);
    }

    function getHeroPower(uint256 heroId) public view returns (uint256) {
        (
            uint8 heroClass,
            uint8 power,
            uint8 speed,
            uint8 defense,
            uint8 luck,
            uint8 rarity,
            uint16 nameSeed
        ) = heroNft.heroStats(heroId);
        nameSeed;

        uint256 total = uint256(power) + uint256(defense) / 2 + uint256(speed) / 3 + uint256(luck) / 5;
        total += _rarityBonus(rarity) + _classBonus(heroClass);

        uint256 weaponId = heroEquippedWeapon[heroId];
        if (weaponId != 0 && weaponNft.ownerOf(weaponId) == heroNft.ownerOf(heroId)) {
            total += weaponNft.bonusDamage(weaponId);
        }
        return total;
    }

    /// @notice Preview LOOT earned on victory (before fight tx)
    function previewReward(uint256 heroId, uint8 tier) external view returns (uint256) {
        require(tier < 5, "Invalid tier");
        return _calcReward(heroId, tier);
    }

    function fight(uint256 heroId, uint8 tier) external nonReentrant returns (bool victory, uint256 reward) {
        require(tier < 5, "Invalid tier");
        require(heroNft.ownerOf(heroId) == msg.sender, "Not hero owner");
        require(block.timestamp >= heroLastFight[heroId] + fightCooldown, "Hero resting");

        uint256 power = getHeroPower(heroId);
        require(power >= tiers[tier].minPower, "Hero too weak for this tier");

        uint256 zombiePower = tiers[tier].minPower + 20;
        uint256 roll = uint256(
            keccak256(abi.encodePacked(block.prevrandao, msg.sender, heroId, tier, block.timestamp))
        ) % 100;

        uint256 winChance = _winChance(power, zombiePower);
        victory = roll < winChance;

        heroLastFight[heroId] = block.timestamp;

        if (victory) {
            reward = _calcReward(heroId, tier);
            totalKills[msg.sender]++;
            heroKillCount[heroId]++;
            totalLootEarned[msg.sender] += reward;
            lootToken.mint(msg.sender, reward);
        }

        emit BattleResult(msg.sender, heroId, tier, victory, power, reward);
    }

    function _calcReward(uint256 heroId, uint8 tier) private view returns (uint256) {
        uint256 reward = tiers[tier].reward;
        uint8 rarity = _heroRarity(heroId);
        if (rarity >= 3) reward = (reward * 120) / 100;
        if (rarity == 4) reward = (reward * 150) / 100;
        return reward;
    }

    function _winChance(uint256 heroPower, uint256 zombiePower) private pure returns (uint256) {
        if (heroPower >= zombiePower * 2) return 90;
        if (heroPower >= zombiePower) return 65 + ((heroPower - zombiePower) * 20) / zombiePower;
        return 25;
    }

    function _heroRarity(uint256 heroId) private view returns (uint8) {
        (, , , , , uint8 rarity, uint16 _ns) = heroNft.heroStats(heroId);
        _ns;
        return rarity;
    }

    function _rarityBonus(uint8 rarity) private pure returns (uint256) {
        if (rarity == 4) return 45;
        if (rarity == 3) return 28;
        if (rarity == 2) return 16;
        if (rarity == 1) return 8;
        return 0;
    }

    function _classBonus(uint8 c) private pure returns (uint256) {
        if (c == 3) return 12;
        if (c == 4) return 10;
        if (c == 0) return 8;
        return 5;
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyRole(UPGRADER_ROLE) {
        emit ContractUpgraded(VERSION);
    }

    uint256[40] private __gap;
}

